"""Build safari collections with correct geography and practical trip notes."""
import build_tours as site
from build_zanzibar import rail

def hero(south=False):
    scenes=[('images/safari-expansion/rufiji-river.webp','Rufiji River in the historic Selous landscape','RUFIJI / SOUTHERN TANZANIA'),('images/safari-expansion/mikumi-elephants.webp','Elephants in Mikumi National Park','MIKUMI / WILDLIFE COUNTRY'),('images/safari-expansion/serengeti-plains.webp','Serengeti river landscape in golden light','SERENGETI / THE NORTHERN CIRCUIT')]
    if not south:scenes=[scenes[2],scenes[1],scenes[0]]
    frames=''.join(f'<figure data-slide class="{("is-active" if n==0 else "")}" aria-hidden="{str(n!=0).lower()}"{(" inert" if n else "")}>{site.img(image,alt,n==0,"100vw")}<figcaption>{caption}</figcaption></figure>' for n,(image,alt,caption) in enumerate(scenes))
    title='River mornings.<span>Wildlife days.</span>' if south else 'Give the wild<br>the time it deserves.<span>Find your safari.</span>'
    intro='Nyerere by road or by air, and Mikumi from Dar es Salaam. Choose the departure point and pace that fit your time in Tanzania.' if south else 'From the northern plains to the Rufiji River. Compare road safaris, fly-in journeys and coast extensions, with the route and costs clearly explained.'
    return f'<section class="daytrip-hero safari-hero" data-carousel role="region" aria-roledescription="carousel" aria-label="Tanzania safari destination photographs"><div class="hero-frames">{frames}</div><div class="daytrip-hero-content"><p class="eyebrow">{("NYERERE · MIKUMI · DAR ES SALAAM" if south else "TANZANIA · NORTHERN PLAINS · SOUTHERN RIVERS")}</p><h1>{title}</h1><p>{intro}</p><div class="hero-buttons"><a class="btn btn-primary" href="#safari-itineraries">Compare the safaris ↗</a><a class="btn btn-secondary" href="index.html?trip=safari#contact">Plan with David</a></div></div><p class="gallery-caption" data-visible-caption>{scenes[0][2]}</p>{site.controls(len(scenes))}</section>'

def build():
    north=['2-day-tarangire-ngorongoro','4-day-serengeti-camping','5-day-northern-lodge-safari','6-day-northern-safari-culture','4-day-luxury-northern-safari']
    south=['3-day-nyerere-road-safari','3-day-nyerere-fly-in-zanzibar','2-day-mikumi-safari']
    body=hero()+'''<div class="daytrip-navigation"><p>Private journeys · actual departure points · written quotes</p><div><a href="#northern-circuit">Northern circuit</a><a href="#southern-circuit">Nyerere &amp; Mikumi</a><a href="#safari-coast">Safari + Zanzibar</a><a href="#migration-planning">Migration planning</a><a href="#private-family">Private &amp; family</a></div></div>'''
    for id,tag,title,intro,ids in [('northern-circuit','THE PLAINS & THE HIGHLANDS','Northern Tanzania,<br>with room to explore.','Start in Arusha. Choose a compact Tarangire–Ngorongoro trip, give the Serengeti several days, or request named luxury lodges and a private pace.',north),('southern-circuit','THE RUFIJI REGION & MIKUMI','A different safari<br>in southern Tanzania.','Road tours begin in Dar es Salaam; the Nyerere fly-in itinerary begins and ends at Zanzibar airport. Compare the travel method before choosing your trip.',south),('safari-coast','A MAINLAND CHAPTER, THEN THE SEA','Connect safari<br>with island time.','The six-day example includes a scheduled mainland-to-island flight and two coast nights. Add more Zanzibar days if you want a longer beach stay.',['6-day-drive-in-safari-zanzibar','safari-zanzibar-journey'])]:
        body+=f'<section class="section safari-collection" id="{id}"><div class="section-heading split-heading"><div><p class="eyebrow">{tag}</p><h2>{title}</h2></div><p>{intro}</p></div>{rail(ids,"safari itineraries")}</section>'
    body+='''<section class="section" id="safari-itineraries"><div class="section-heading"><p class="eyebrow">CHOOSE THE ROUTE BEFORE THE ROOM</p><h2>Where does your safari begin?</h2></div><div class="safari-region-grid"><article><h3>Arusha &amp; the northern circuit</h3><p>Tarangire, Lake Manyara, Ngorongoro and the Serengeti work as a northern road circuit. A four-day highland trip and a longer Serengeti journey serve different priorities.</p><a href="#northern-circuit">Compare northern routes ↗</a></article><article><h3>Dar es Salaam &amp; the south</h3><p>Mikumi and Nyerere road safaris use Dar es Salaam as their stated departure. A northern safari vehicle is not assumed to transfer to those parks at no extra cost.</p><a href="southern-safaris.html">Explore southern safaris ↗</a></article></div></section><section class="section" id="migration-planning"><div class="safari-editorial"><p class="eyebrow">THE SERENGETI, BY SEASON</p><h2>Plan for wildlife.<br>Leave room for nature.</h2><p>Migration routes and timing vary with rainfall and grazing. Southern Serengeti/Ndutu can suit a calving-season enquiry; northern Serengeti plans require the right camps and enough road or flight time. A crossing or a specific animal sighting is never guaranteed.</p><p>Your quote should name the safari area, camp nights, transfer method and permits. An image of a river crossing is not a promise that it will happen on your dates.</p><a class="btn btn-primary" href="index.html?trip=safari#contact">Ask about my travel month ↗</a></div></section><section class="section" id="private-family"><div class="section-heading"><p class="eyebrow">YOUR PARTY. YOUR PACE.</p><h2>Plan the safari<br>around the people travelling.</h2></div><div class="promise-grid"><article><h3>Private vehicle</h3><p>Agree who shares the vehicle, luggage capacity and actual transfer arrangements. Private does not automatically mean a chartered aircraft or an exclusive boat.</p></article><article><h3>Families &amp; access needs</h3><p>Share ages, room preferences, mobility needs and dietary requirements. Camp age rules and optional activities need confirmation before quoting.</p></article><article><h3>Comfort &amp; camp choice</h3><p>Compare camping, lodges and tented camps with named properties and room categories. Decide what matters to you rather than relying on a general luxury label.</p></article></div></section>'''
    body+=site.EXPLAIN+'<section class="section destination-final-cta"><p class="eyebrow">LET’S BUILD THE ROUTE</p><h2>Tell David where<br>you’ll arrive.</h2><p>Share your dates, group and preferred parks. We’ll connect the activities and transfers into a trip that fits.</p><a class="btn btn-primary" href="index.html?trip=safari#contact">Request my safari plan ↗</a></section>'
    site.page('safari.html','Tanzania Private Safaris: Northern & Southern Routes','Compare private northern circuit, Nyerere fly-in and road, Mikumi, luxury and safari–Zanzibar itineraries with practical departure and price information.',body,'images/safari-expansion/serengeti-plains.webp')
    body=hero(True)+'<section class="section" id="safari-itineraries"><div class="section-heading split-heading"><div><p class="eyebrow">THREE PRACTICAL STARTING ROUTES</p><h2>Road or air.<br>Choose how you arrive.</h2></div><p>Compare two Dar es Salaam road departures with the scheduled Zanzibar–Nyerere flight plan. Accommodation, transport, fees and the complete total are confirmed for your actual dates.</p></div><div class="package-grid">'+site.selected_cards(south)+'</div>'+site.EXPLAIN+'</section>'
    body+='''<section class="section"><div class="safari-region-grid"><article><h3>Nyerere &amp; the Rufiji region</h3><p>A river-based activity brings another view of the landscape alongside game drives. Boat conditions and permissions are checked; walking requires a separate authorised arrangement.</p><a href="https://www.tanzaniaparks.go.tz/nyerere/visitor-guide">Read TANAPA’s Nyerere visitor guide ↗</a></article><article><h3>Mikumi &amp; the Mkata floodplain</h3><p>A one-night Mikumi visit can fit a short Dar es Salaam road safari. Transfer time is part of the trip; avoid a tight onward flight after the return drive.</p><a href="https://www.tanzaniaparks.go.tz/mikumi/visitor-guide">Read TANAPA’s Mikumi visitor guide ↗</a></article></div></section><section class="section destination-final-cta"><p class="eyebrow">YOUR SOUTHERN SAFARI</p><h2>Start with your arrival point.</h2><p>Tell David whether you’ll be in Dar es Salaam or Zanzibar, and how many safari nights you have.</p><a class="btn btn-primary" href="index.html?trip=safari#contact">Plan my southern safari ↗</a></section>'''
    site.page('southern-safaris.html','Nyerere & Mikumi Safaris from Dar es Salaam or Zanzibar','Compare Nyerere road safaris from Dar es Salaam, Nyerere fly-in trips from Zanzibar and two-day Mikumi road safaris.',body,'images/safari-expansion/rufiji-river.webp')
    site.sitemap();print('Built northern and southern safari collections')
if __name__=='__main__':build()
